use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

const EPS: i32 = 2;

// A simple Complex type with 32-bit integer real and imaginary parts.
#[verifier(external_body)]
#[derive(Clone)]
pub struct Complex {
    pub re: i32,
    pub im: i32,
}

// Specification function for absolute value of an i32.
spec fn abs_i32(x: i32) -> i32 {
    if x < 0 { -x } else { x }
}

// Predicate: the imaginary part of c is "close to zero" under tolerance tol.
spec fn is_close(c: Complex, tol: i32) -> bool {
    abs_i32(c.im) <= tol * EPS
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> (result: Vec<Complex>)
    requires
        tol > 0,
    ensures
        // Same length always.
        result.len() == arr.len(),
        // Real parts are always preserved.
        forall |i: usize| i < arr.len() ==> result.index(i).re == arr.index(i).re,
        // If every element is close, then we zero‐out all imag parts,
        // otherwise we leave imag parts unchanged.
        if forall |i: usize| i < arr.len() ==> is_close(arr.index(i), tol) {
            forall |i: usize| i < arr.len() ==> result.index(i).im == 0
        } else {
            forall |i: usize| i < arr.len() ==> result.index(i).im == arr.index(i).im
        }
{
    let n = arr.len();

    // First pass: determine whether every imaginary part is close.
    let mut all_close: bool = true;
    let mut idx: usize = 0;
    // Invariant relates all_close to the elements seen so far.
    while idx < n
        invariant
            idx <= n,
            // If all_close is true then all seen elements are close.
            (all_close) ==> forall |j: usize| j < idx ==> is_close(arr.index(j), tol),
            // If all_close is false then there is some seen element that is not close.
            (!all_close) ==> exists |j: usize| j < idx && !is_close(arr.index(j), tol),
        decreases n - idx
    {
        if all_close {
            // only check while we're still "optimistic"
            if !is_close(arr.index(idx), tol) {
                all_close = false;
            }
        }
        idx += 1;
    }

    // Second pass: build the result vector.
    if all_close {
        // Every element is close: zero out imaginary parts.
        let mut out: Vec<Complex> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant i <= n,
            invariant out.len() == i,
            // real part of each pushed element matches
            invariant forall |j: usize| j < out.len() ==> out.index(j).re == arr.index(j).re,
            // imag part is zero
            invariant forall |j: usize| j < out.len() ==> out.index(j).im == 0,
            decreases n - i
        {
            let a = arr.index(i);
            out.push(Complex { re: a.re, im: 0 });
            i += 1;
        }
        result = out;
    } else {
        // Not all are close: return the original array unchanged.
        // Vec::clone preserves length, re, and im.
        result = arr.clone();
    }
}

} // verus! 

